def balanced(text, start):
    if text[start] != '(':
        raise ValueError('Expected opening parenthesis')
    depth = 0
    for index in range(start, len(text)):
        if text[index] == '(':
            depth += 1
        elif text[index] == ')':
            depth -= 1
            if not depth:
                return text[start + 1:index], index + 1
    raise ValueError('Unbalanced assertion')


